const expect=baseExpect.configure({timeout:30000}),hash=b=>createHash('sha256').update(b).digest('hex')
export function readPackage(bytes){const files={};let offset=0;while(bytes.readUInt32LE(offset)===0x04034b50){const size=bytes.readUInt32LE(offset+18),n=bytes.readUInt16LE(offset+26),extra=bytes.readUInt16LE(offset+28),name=bytes.subarray(offset+30,offset+30+n).toString(),start=offset+30+n+extra;files[name]=bytes.subarray(start,start+size);offset=start+size}expect(bytes.readUInt32LE(offset)).toBe(0x02014b50);const manifest=JSON.parse(files['manifest.json']);for(const f of manifest.files){expect(files[f.name].length).toBe(f.bytes);expect(hash(files[f.name])).toBe(f.sha256)}return {files,manifest,records:JSON.parse(files['records.json'])}}
export async function operationsWorkflow({browser,origin,actors,options={},capture=async()=>{},record=()=>{},admin}){
 const f=await prepareCrew(actors,'SYNTHETIC operations'),{company,siteId,briefId,actionId,version}=f,contexts=[],date=todayInZone(),site='/sites/'+siteId,api=origin+'/api/sites/'+siteId
 const rpc=(role,fn,command,p)=>actors[role].client.rpc(fn,{command,p:{companyId:company,requestId:randomUUID(),...p}}).then(expectSuccess),rows=(table,key,id)=>actors.OWNER.client.from(table).select('*').eq(key,id).then(expectSuccess)
 const current=async()=>(await rows('ts_actions','id',actionId))[0],events=()=>rows('ts_events','entity_id',actionId)
 let stage='login'
 async function login(role){const {localOnly,...settings}=options,c=await browser.newContext({viewport:{width:390,height:844},...settings});contexts.push(c);if(localOnly)await c.route('**/*',r=>[origin,actors[role].apiOrigin].includes(new URL(r.request().url()).origin)?r.continue():r.abort());const p=await c.newPage();p.setDefaultTimeout(30000);p.setDefaultNavigationTimeout(90000);await p.goto(origin+'/auth/login');await p.getByLabel('Email',{exact:true}).fill(actors[role].email);await p.getByLabel('Password',{exact:true}).fill(actors[role].password);await p.getByRole('button',{name:'Sign In',exact:true}).click();await p.waitForURL('**/dashboard');return p}
 const postPackage=(page,start=date,end=date)=>page.context().request.post(api+'/package?'+new URLSearchParams({start,end}),{headers:{origin,'x-expected-actor':page===worker?actors.WORKER.id:actors.SUPERVISOR.id},timeout:120000})
 let worker
 try{
 const sup=await login('SUPERVISOR');worker=await login('WORKER');const outsider=await login('OUTSIDER')
 stage='planning-lost-response';await sup.goto(origin+'/actions?'+new URLSearchParams({company,site:siteId,mine:'0',focus:actionId}));const card=sup.locator('#action-'+actionId);await card.getByText('Assignment, due date and immediate controls',{exact:true}).click();await card.getByLabel('Due date (optional)',{exact:true}).fill(date);await card.getByLabel('Operational priority',{exact:true}).selectOption('high')
 let lost=false;await sup.context().route('**/api/workspace',async r=>{if(r.request().postDataJSON()?.command==='update_action'&&!lost){lost=true;expect((await r.fetch()).status()).toBe(200);await r.abort()}else await r.continue()});await card.getByRole('button',{name:'Save progress',exact:true}).click();await expect(card.getByRole('button',{name:'Retry action update',exact:true})).toBeVisible();await card.getByRole('button',{name:'Retry action update',exact:true}).click();await expect(card.getByRole('status').filter({hasText:'Action update saved.'})).toBeVisible();await sup.context().unroute('**/api/workspace');expect((await current()).priority).toBe('high');expect((await events()).filter(e=>e.kind==='action_updated')).toHaveLength(1)
 await sup.reload();await expect(card.getByText(/Due today.*High priority/)).toBeVisible();await capture(sup,'supervisor-planning');stage='clear-and-restore-planning';await card.getByText('Assignment, due date and immediate controls',{exact:true}).click();await card.getByLabel('Due date (optional)',{exact:true}).fill('');await card.getByLabel('Operational priority',{exact:true}).selectOption('unspecified');await card.getByRole('button',{name:'Save progress',exact:true}).click();await expect(card.getByRole('status').filter({hasText:'Action update saved.'})).toBeVisible();expect((await current()).target_date).toBe(null);expect((await current()).priority).toBe('unspecified');await card.getByLabel('Due date (optional)',{exact:true}).fill(date);await card.getByLabel('Operational priority',{exact:true}).selectOption('high');await card.getByRole('button',{name:'Save progress',exact:true}).click();await expect(card.getByRole('status').filter({hasText:'Action update saved.'})).toBeVisible()
 stage='worker-filter-and-permissions';await worker.goto(origin+'/my-work?'+new URLSearchParams({company,deadline:'today',priority:'high',sort:'priority'}));await expect(worker.getByRole('status').filter({hasText:'1 outstanding actions assigned to you'})).toBeVisible();await worker.getByRole('link',{name:/SYNTHETIC blocked route/}).click();await expect(worker.getByLabel('Operational priority',{exact:true})).toHaveCount(0);await expect(worker.getByLabel('Due date (optional)',{exact:true})).toHaveCount(0)
 let a=await current(),payload={id:a.id,revision:a.revision,requestId:randomUUID(),state:'open',responsibleId:a.responsible_id,targetDate:date,priority:'low',controls:a.controls,resolution:a.resolution}
 expectDatabaseError(await actors.WORKER.client.rpc('ts_command',{command:'update_action',p:{companyId:company,...payload}}),'TS_denied')
 stage='deadline-closure-reopen';a=await rpc('SUPERVISOR','ts_command','update_action',{...payload,priority:'high',state:'closed',resolution:'SYNTHETIC verified'});let summary=expectSuccess(await actors.SUPERVISOR.client.rpc('ts_site_handover',{site:siteId,day:date,zone:'America/Toronto'}));expect(summary.outstanding).toHaveLength(0)
 a=await rpc('SUPERVISOR','ts_command','update_action',{...payload,requestId:randomUUID(),revision:a.revision,priority:'high',state:'open'});expect(a.target_date).toBe(date)
 expectDatabaseError(await actors.SUPERVISOR.client.rpc('ts_command',{command:'update_action',p:{companyId:company,...payload,requestId:randomUUID(),priority:'high'}}),'TS_conflict')
 stage='brief-exact-versions';await rpc('WORKER','ts_brief_command','acknowledge',{id:briefId,version});const originalVersion=(await rows('ts_brief_versions','brief_id',briefId))[0];let b=(await rows('ts_briefs','id',briefId))[0];b=await rpc('SUPERVISOR','ts_brief_command','revise',{id:briefId,revision:b.revision});b=await rpc('SUPERVISOR','ts_brief_command','save',{id:briefId,revision:b.revision,document:{...b.document,briefingNote:'SYNTHETIC revised operations'}});await rpc('SUPERVISOR','ts_brief_command','record',{id:briefId,revision:b.revision})
 stage='concern-photo';await worker.goto(origin+site);await worker.getByRole('link',{name:'Report a concern',exact:true}).click();await worker.getByLabel('What did you observe?',{exact:true}).fill('SYNTHETIC operations blue marker');await worker.getByLabel('Where on this site?',{exact:true}).fill('SYNTHETIC north bay');await worker.getByRole('button',{name:'Save concern draft',exact:true}).click();await worker.waitForURL(/\/concerns\/[a-f0-9-]{36}$/);const concernId=new URL(worker.url()).pathname.split('/').at(-1)
 const photo=await sharp(Buffer.from('<svg width="320" height="240"><rect width="320" height="240" fill="white"/><rect x="80" y="50" width="140" height="140" fill="blue"/><text x="15" y="225" font-size="20">SYNTHETIC OPERATIONS</text></svg>')).jpeg().toBuffer();await worker.getByLabel('Photo file',{exact:true}).setInputFiles({name:'SYNTHETIC-blue-marker.jpg',mimeType:'image/jpeg',buffer:photo});await worker.getByLabel('Photo caption',{exact:true}).fill('SYNTHETIC blue marker north bay');await worker.getByRole('button',{name:'Upload photo',exact:true}).click();await expect(worker.getByRole('status').filter({hasText:'Photo saved and retained.'})).toBeVisible();await worker.getByRole('button',{name:'Submit concern',exact:true}).click();await worker.getByRole('link',{name:'View concern and follow-up',exact:true}).click()
 const photoRow=(await rows('ts_concern_photos','concern_id',concernId))[0],photoResponse=await worker.context().request.get(origin+'/api/concerns/'+concernId+'/evidence/'+photoRow.id),photoBytes=await photoResponse.body();expect(hash(photoBytes)).toBe(photoRow.sha256)
 stage='report-and-retained-pdf';let report=await rpc('SUPERVISOR','ts_site_command','create_report',{id:randomUUID(),siteId,templateId:getTemplate('electrical').id});const answers=buildChecklistState('electrical');for(const answer of Object.values(answers))answer.state='meets';report=await rpc('SUPERVISOR','ts_command','save_report',{id:report.id,revision:report.revision,document:{job:{address:f.tag,client:'SYNTHETIC operations',date},answers}});report=await rpc('SUPERVISOR','ts_command','finalize',{id:report.id,revision:report.revision,acknowledged:true});const locked=await rows('ts_reports','id',report.id)
 const missing=await postPackage(sup);expect(missing.status()).toBe(503);expect((await missing.json()).code).toBe('package_missing')
 const pdfs={};for(const original of [true,false]){if(!original){report=await rpc('SUPERVISOR','ts_command','amend',{id:randomUUID(),amendmentOf:locked[0].id,reason:'SYNTHETIC separate operations correction'});report=await rpc('SUPERVISOR','ts_command','finalize',{id:report.id,revision:report.revision,acknowledged:true})}const endpoint=origin+'/api/reports/'+report.id+'/exports',r=await sup.context().request.post(endpoint,{headers:{origin},timeout:90000});expect(r.status()).toBe(200);const x=await r.json();pdfs[report.id]=await(await sup.context().request.get(endpoint+'/'+x.id)).body()}
 stage='history-mobile';await sup.goto(origin+site);const history=sup.getByRole('region',{name:'Site history',exact:true});stage='history-date-reentry';await history.getByLabel('History from',{exact:true}).fill('');await expect(history.getByLabel('History from',{exact:true})).toBeEditable();await history.getByLabel('History from',{exact:true}).fill(date);stage='history-type-filter';await history.getByLabel('Record type',{exact:true}).selectOption('concern');stage='history-text-filter';await history.getByLabel('Search site history',{exact:true}).fill('blue marker');stage='history-submit';await history.getByRole('button',{name:'Search history',exact:true}).click();stage='history-search-result';await expect(history.getByRole('status')).toContainText('1 records on this page');stage='history-open-record';await history.getByRole('link',{name:/SYNTHETIC operations blue marker/}).focus();await sup.keyboard.press('Enter');stage='history-return-link';await sup.getByRole('link',{name:'Back to site',exact:true}).click();stage='history-return-filters';await expect(history.getByLabel('Search site history',{exact:true})).toHaveValue('blue marker');stage='history-return-results';await expect(history.getByRole('status')).toContainText('1 records on this page');await capture(sup,'site-history')
 await sup.context().route('**/api/sites/*/history?*',r=>r.abort());await history.getByRole('button',{name:'Search history',exact:true}).click();await expect(history.getByRole('button',{name:'Retry history',exact:true})).toBeVisible();await sup.context().unroute('**/api/sites/*/history?*');await history.getByRole('button',{name:'Retry history',exact:true}).click();await expect(history.getByRole('status')).toContainText('1 records on this page')
 stage='package-actual-download';const panel=sup.getByRole('region',{name:'Evidence package',exact:true});let dropped=false;await sup.context().route('**/api/sites/*/package?*',async r=>{if(!dropped){dropped=true;expect((await r.fetch({timeout:120000})).status()).toBe(200);await r.abort()}else await r.continue()});await panel.getByRole('button',{name:'Download evidence package',exact:true}).click();await expect(panel.getByRole('button',{name:'Retry evidence package',exact:true})).toBeVisible();await sup.context().unroute('**/api/sites/*/package?*');const downloaded=sup.waitForEvent('download');await panel.getByRole('button',{name:'Retry evidence package',exact:true}).click();const download=await downloaded,stream=await download.createReadStream(),chunks=[];for await(const chunk of stream)chunks.push(chunk);const parsed=readPackage(Buffer.concat(chunks));expect(parsed.records.briefs).toHaveLength(2);expect(parsed.records.acknowledgements).toHaveLength(1);expect(parsed.records.acknowledgements[0].version).toBe(version);expect(parsed.files['photos/'+photoRow.id+'.jpg']).toEqual(photoBytes);for(const [id,bytes] of Object.entries(pdfs))expect(parsed.files['reports/'+id+'.pdf']).toEqual(bytes);expect(parsed.files['index.html'].toString()).toContain('SYNTHETIC blue marker north bay');expect(parsed.records.reports.find(r=>r.amendment_of)?.amendment_of).toBe(locked[0].id);expect(JSON.stringify(parsed.manifest)).not.toMatch(/object_path|https?:|password|token/)
 for(const width of [320,390]){await sup.setViewportSize({width,height:844});expect(await sup.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true)}await capture(sup,'evidence-package')
 stage='limits-permissions-and-originals';expect((await postPackage(sup,'2026-01-01','2026-03-01')).status()).toBe(422);expect((await outsider.context().request.get(api+'/history?'+new URLSearchParams({start:date,end:date}))).status()).toBe(404);expect((await outsider.context().request.post(api+'/package?'+new URLSearchParams({start:date,end:date}),{headers:{origin}})).status()).toBe(404)
 if(admin){stage='local-missing-private-object';expectSuccess(await admin.storage.from('tradesafe-evidence').remove([photoRow.object_path]));try{const bad=await postPackage(sup);expect(bad.status()).toBe(503);expect((await bad.json()).code).toBe('package_missing')}finally{expectSuccess(await admin.storage.from('tradesafe-evidence').upload(photoRow.object_path,photoBytes,{contentType:'image/jpeg',upsert:false}))}}
 await rpc('OWNER','ts_command','member',{userId:actors.WORKER.id,role:'remove'});expect((await worker.context().request.get(api+'/history?'+new URLSearchParams({start:date,end:date}))).status()).toBe(404);expect((await postPackage(worker)).status()).toBe(404);expect(await rows('ts_reports','id',locked[0].id)).toEqual(locked);expect((await rows('ts_brief_versions','brief_id',briefId)).find(v=>v.version===version)).toEqual(originalVersion);expect(hash(await(await sup.context().request.get(origin+'/api/concerns/'+concernId+'/evidence/'+photoRow.id)).body())).toBe(photoRow.sha256)
 record('PASS planning, history, ZIP hashes, exact acknowledgements, interruptions, roles and retained originals',{...f,concernId,photoHash:photoRow.sha256,pdfHashes:Object.fromEntries(Object.entries(pdfs).map(([id,b])=>[id,hash(b)])),packageFiles:Object.keys(parsed.files),localMissingObjectExecuted:!!admin})
 }catch(e){mkdirSync('test-results',{recursive:true});writeFileSync('test-results/operations-stage.json',JSON.stringify({stage,name:e.name,operation:e.message?.match(/^(?:locator|page)\.\w+/)?.[0]||null,assertion:e.matcherResult?.name||null}));throw e}finally{for(const c of contexts)await c.close()}
}
